import {ContractError,chinaDate,validDate} from './cloud-contract.mjs';
import {hasSensitive} from './admin-permissions.mjs';
const fail=()=>{throw new ContractError('资源归属或套餐资料不完整，请刷新核对。');};
const id=v=>{if(typeof v!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(v))fail();return v;};
const int=(v,min=0)=>{if(!Number.isSafeInteger(v)||v<min||v>=2147483647)fail();return v;};
const text=(v,max,required=false)=>{if(typeof v!=='string'||v.length>max||required&&!v.trim())fail();return v.trim();};
export const profileScopes={public:'工作室公共',store:'店铺专属',unclassified:'归属待确认'},planCycles={monthly:'每月',yearly:'每年','one-off':'一次性',unknown:'周期待确认'};
export const profileKind=k=>{if(!['equipment-store','card-plan'].includes(k))fail();return k;};
const amount=n=>n===null?'金额待确认':'¥'+(n/100).toFixed(2);
export function resourceProfileState(v,kind,owner){if(!v||v.kind!==kind||v.target?.id!==owner||!Array.isArray(v.stores)||!v.history||!Array.isArray(v.history.rows)||v.history.rows.length>50||v.history.limit!==50)fail();profileKind(kind);id(v.target.id);int(v.target.version,1);text(v.target.name,200,true);text(v.target.code,64,true);int(v.history.total);int(v.history.offset);
 const record=r=>{id(r.id);int(r.version,1);text(r.reason,2000,true);text(r.actor,100,true);if(!Number.isFinite(Date.parse(r.createdAt)))fail();if(kind==='equipment-store'){if(!Object.hasOwn(profileScopes,r.scope))fail();if(r.scope==='store'){id(r.storeId);text(r.storeName,150,true);}else if(r.storeId!==null||r.storeName!==null)fail();}else{if(!Object.hasOwn(planCycles,r.cycle)||r.fixedCents!==null&&(!Number.isSafeInteger(r.fixedCents)||r.fixedCents<0||r.fixedCents>2147483647)||!validDate(r.effectiveOn))fail();text(r.planName,200,true);text(r.details,2000);if(r.billingDay!==null&&(!Number.isInteger(r.billingDay)||r.billingDay<1||r.billingDay>31||r.cycle!=='monthly'))fail();if(r.cardSnapshot?.id!==owner)fail();id(r.cardSnapshot.id);int(r.cardSnapshot.version,1);text(r.cardSnapshot.phoneNumber,40,true);}};
 if(v.record!==null)record(v.record);if(v.current!==null)record(v.current);v.history.rows.forEach(record);for(const s of v.stores){id(s.id);text(s.name,150,true);if(typeof s.active!=='boolean')fail();}return v;
}
export function resourceProfilePayload(kind,v){profileKind(kind);const extra=kind==='equipment-store'?['scope','storeId']:['planName','fixedFee','cycle','billingDay','effectiveOn','details'],keys=['requestKey','expectedVersion','targetVersion','reason',...extra];if(!v||Object.keys(v).some(k=>!keys.includes(k))||keys.some(k=>!Object.hasOwn(v,k)))fail();const out={requestKey:id(v.requestKey),expectedVersion:int(v.expectedVersion),targetVersion:int(v.targetVersion,1),reason:text(v.reason,2000,true)};
 if(kind==='equipment-store'){if(!Object.hasOwn(profileScopes,v.scope))fail();if(v.scope==='store')id(v.storeId);else if(v.storeId!==null)fail();return {...out,scope:v.scope,storeId:v.storeId};}
 if(!Object.hasOwn(planCycles,v.cycle)||v.fixedFee!==null&&(typeof v.fixedFee!=='string'||!/^\d{1,8}(?:\.\d{1,2})?$/.test(v.fixedFee)||Number(v.fixedFee)*100>2147483647)||!validDate(v.effectiveOn)||v.billingDay!==null&&(!Number.isInteger(v.billingDay)||v.billingDay<1||v.billingDay>31||v.cycle!=='monthly'))fail();return {...out,planName:text(v.planName,200,true),fixedFee:v.fixedFee,cycle:v.cycle,billingDay:v.billingDay,effectiveOn:v.effectiveOn,details:text(v.details,2000)};
}
export function createResourceProfileEditors({api,h,mount,input,select,area}){
 async function resourceProfile(kind,owner){const s=await api.resourceProfile(kind,owner),r=s.record,key=crypto.randomUUID(),equipment=kind==='equipment-store';const body=equipment?`<p class="planning-rule">设备独立归属与运营账号、手机卡归属分别记录；交接或账号变化不会自动改归属。</p>`+select('scope','设备归属',r?.scope??'unclassified',Object.entries(profileScopes))+select('storeId','专属店铺',r?.storeId??'',[['','公共或待确认时不选择'],...s.stores.filter(v=>v.active||v.id===r?.storeId).map(v=>[v.id,v.name+(v.active?'':'（已停用）')])]):`<p class="planning-rule">固定资费是套餐计划，允许明确零元或暂未确认。它不自动生成支出、充值或月度扣费。实际费用仍沿用原记账和充值记录；每月扣费日超过当月天数时按当月最后一天理解，本轮仅记资料。</p>`+input('planName','套餐名称',r?.planName??'','required maxlength="200"')+input('fixedFee','每个周期固定资费（元，未确认留空）',r?.fixedCents==null?'':(r.fixedCents/100).toFixed(2),'inputmode="decimal" maxlength="12"')+select('cycle','资费周期',r?.cycle??'unknown',Object.entries(planCycles))+input('billingDay','月扣费日（仅每月套餐，未确认留空）',r?.billingDay??'','type="number" min="1" max="31" step="1"')+input('effectiveOn','本次套餐生效日期',r?.effectiveOn??chinaDate(),'required type="date"')+area('details','套餐流量、通话与其他说明',r?.details??'');
  mount(equipment?'设备店铺归属':'手机卡套餐与固定资费',`<p>${h(s.target.code)} · ${h(s.target.name)}</p>`+body+area('reason','本次核对或修正原因（必填）'),f=>api.saveResourceProfile(kind,owner,{requestKey:key,expectedVersion:r?.version??0,targetVersion:s.target.version,reason:f.get('reason'),...(equipment?{scope:f.get('scope'),storeId:f.get('scope')==='store'?f.get('storeId')||null:null}:{planName:f.get('planName'),fixedFee:f.get('fixedFee').trim()||null,cycle:f.get('cycle'),billingDay:f.get('billingDay')?Number(f.get('billingDay')):null,effectiveOn:f.get('effectiveOn'),details:f.get('details')})}),{kind:'resource-profile',profileKind:kind,id:owner},()=>api.resourceProfileReceipt(kind,owner,key));
 }return {resourceProfile};
}
export function createResourceProfileViews({api,h,showPanel,getUser,writable,notify,localTime}){
 const describe=r=>r.scope!==undefined?profileScopes[r.scope]+(r.storeName?' · '+r.storeName:''):r.planName+' · '+amount(r.fixedCents)+' / '+planCycles[r.cycle]+(r.billingDay?' · 月扣费日 '+r.billingDay+' 日':'')+' · 生效 '+r.effectiveOn;
 async function detail(kind,owner,offset=0){await showPanel('资源归属与套餐',async signal=>{const s=await api.resourceProfile(kind,owner,offset,signal),equipment=kind==='equipment-store';return `<div class="dialog-header"><h2>${equipment?'设备店铺归属':'手机卡套餐与固定资费'}</h2><button class="icon-button" data-resource-profile-close aria-label="关闭归属与套餐">×</button></div><p>${h(s.target.code)} · ${h(s.target.name)}</p><p class="planning-rule">${equipment?'设备归属独立记录，不按关联账号或手机卡自动推断。':'套餐为计划资料，非实际支出或充值；未来生效的版本不会提前显示为当前套餐。'}</p><p>当前${equipment?'归属':'生效套餐'}：${s.current?h(describe(s.current)):'尚未确认'}</p>${s.record&&s.record.id!==s.current?.id?`<p>最近登记：${h(describe(s.record))}</p>`:''}${writable&&hasSensitive(getUser(),'resources')?`<button class="primary" data-resource-profile-edit="${kind}" data-id="${h(owner)}">核对或修正</button>`:''}<h3>不可改写的变更历史</h3>${s.history.rows.map(r=>`<article class="observation"><b>第 ${r.version} 版 · ${h(describe(r))}</b>${r.details?`<p class="preserve-text">${h(r.details)}</p>`:''}${r.cardSnapshot?`<p>登记时号码：${h(r.cardSnapshot.phoneNumber)}</p>`:''}<p class="preserve-text">${h(r.reason)}</p><small>${h(r.actor)} · ${h(localTime(r.createdAt))}</small></article>`).join('')||'<p class="muted">尚无核对记录。</p>'}<div class="pager"><button class="secondary" data-resource-profile="${kind}" data-id="${h(owner)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${s.history.total} 条</span><button class="secondary" data-resource-profile="${kind}" data-id="${h(owner)}" data-offset="${offset+50}" ${offset+50>=s.history.total?'disabled':''}>下一页</button></div>`;});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-resource-profile-close]'))document.querySelector('#cloud-detail').close();const b=e.target.closest('[data-resource-profile]');if(b)detail(b.dataset.resourceProfile,b.dataset.id,Number(b.dataset.offset||0)).catch(e=>notify(e.message));});return {detail};
}
